    "stem": "4721 sayılı Türk Medeni Kanunu'nun 24. ve 25. maddelerine göre kişilik hakkına hukuka aykırı saldırıda bulunulan kişinin açabileceği davalar ile ilgili aşağıdaki ifadelerden hangisi yanlıştır?",
