    "qNumber": 15,
    "stem": "4721 sayılı Türk Medeni Kanunu'nun 988. ve 989. maddelerine göre zilyetliğe ve taşınır mülkiyetinin iyiniyetle kazanılmasına ilişkin aşağıdaki ifadelerden hangisi yanlıştır?",
