    "stem": "5237 sayılı Türk Ceza Kanunu'nun 21. ve 22. maddelerinde düzenlenen olası kast ile bilinçli taksir arasındaki ayrım çerçevesinde aşağıdaki ifadelerden hangisi doğrudur?",
